<?php
defined('ABSPATH') || exit;

/** Five everyday sections; expert screens retain their original secure routes. */
final class CAFCC_Owner_UI {
    public static $advanced=array();
    public static function init(){
        add_action('admin_menu',function(){if(!CAFCC_Repository::admin_allowed())return;global $submenu;foreach($submenu['cafcc']??array() as $item){if($item[2]!=='cafcc')self::$advanced[]=array('title'=>wp_strip_all_tags($item[0]),'slug'=>$item[2]);remove_submenu_page('cafcc',$item[2]);}
            add_submenu_page('cafcc','Dashboard','Dashboard','manage_options','cafcc',array('CAFCC_Admin','render'));
            foreach(array('cafcc-upload'=>'Upload Questions','cafcc-library'=>'Question Library','cafcc-students'=>'Students','cafcc-settings'=>'Settings') as $slug=>$title)add_submenu_page('cafcc',$title,$title,'manage_options',$slug,array(__CLASS__,'screen'));
        },999);
        add_action('admin_enqueue_scripts',function(){if(!CAFCC_Repository::admin_allowed()||!in_array($_GET['page']??'',array('cafcc','cafcc-upload','cafcc-library','cafcc-settings','cafcc-students'),true))return;wp_enqueue_style('cafcc-owner',plugins_url('assets/owner.css',CAFCC_FILE),array(),CAFCC_VERSION);wp_enqueue_script('cafcc-owner',plugins_url('assets/owner.js',CAFCC_FILE),array(),CAFCC_VERSION,true);wp_localize_script('cafcc-owner','CAFCCOwner',array('url'=>rest_url('cafcc/v8/admin/'),'package_url'=>rest_url('cafcc/v7/admin/'),'studio_url'=>rest_url('cafcc/v4/admin/'),'nonce'=>wp_create_nonce('wp_rest')));if(($_GET['page']??'')==='cafcc-students'){wp_enqueue_style('cafcc-studio',plugins_url('assets/studio.css',CAFCC_FILE),array(),CAFCC_VERSION);wp_enqueue_script('cafcc-access',plugins_url('assets/access-admin.js',CAFCC_FILE),array(),CAFCC_VERSION,true);wp_localize_script('cafcc-access','CAFCCAccess',array('url'=>rest_url('cafcc/v4/admin/'),'nonce'=>wp_create_nonce('wp_rest')));}});
        add_action('rest_api_init',function(){$p=function($r){return CAFCC_REST::permission($r,true);};register_rest_route('cafcc/v8','/admin/dashboard',array('methods'=>'GET','permission_callback'=>$p,'callback'=>array(__CLASS__,'dashboard')));register_rest_route('cafcc/v8','/admin/detail/(?P<id>[1-9][0-9]*)',array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){$v=CAFCC_Studio::get((int)$r['id']);if(!$v)return CAFCC_Repository::error('Question not found.',404);$v['checklist']=CAFCC_Owner::preview_quality($v);$v['search_tags']=CAFCC_Search_Tags::for_review($v['id']);global $wpdb;$v['history']=$wpdb->get_results($wpdb->prepare('SELECT id,revision,actor_id,action,created_at FROM '.CAFCC_Bank_DB::table('audit').' WHERE review_id=%d ORDER BY id DESC LIMIT 30',$v['id']),ARRAY_A);return $v;}));});
    }
    public static function dashboard(){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator required.',403);
        global $wpdb;$t=CAFCC_Studio::table();$counts=$wpdb->get_row("SELECT COUNT(*) AS imported,COALESCE(SUM(publication_status='published' AND archived=0),0) AS published,COALESCE(SUM(publication_status<>'published' AND archived=0),0) AS unpublished,COALESCE(SUM(archived=1),0) AS archived,COALESCE(SUM(owner_answer_state='pending' OR JSON_UNQUOTE(JSON_EXTRACT(payload,'$.blocking_exceptions')) REGEXP 'table_word_assignment|implausibly_narrow|prior_answer_conflict|answer_workings|source_amount_punctuation|integrity_failed|question_incomplete'),0) AS attention FROM $t",ARRAY_A);$sessions=CAFCC_Study::table('sessions');$activity=$wpdb->get_row("SELECT COUNT(DISTINCT user_id) AS students,COUNT(*) AS sessions,COALESCE(SUM(active_seconds),0) AS seconds FROM $sessions",ARRAY_A);$current=(int)get_option('cafcc_current_package',0);$membership=CAFCC_Owner::table('membership');$pilot=$wpdb->get_row($wpdb->prepare("SELECT COUNT(DISTINCT r.id) AS imported,COUNT(DISTINCT CASE WHEN r.publication_status='published' AND r.archived=0 THEN r.id END) AS published FROM $t r JOIN $membership m ON m.review_id=r.id WHERE m.package_id=%d",$current),ARRAY_A);return array('current_dataset'=>$pilot,'counts'=>$counts,'by_source'=>$wpdb->get_results("SELECT source_type AS label,COUNT(*) AS questions FROM $t GROUP BY source_type",ARRAY_A),'by_subject'=>$wpdb->get_results("SELECT subject_code AS label,COUNT(*) AS questions FROM $t GROUP BY subject_code",ARRAY_A),'recent_imports'=>CAFCC_Owner::packages(),'activity'=>$activity);
    }
    public static function screen(){
        if(!CAFCC_Repository::admin_allowed())wp_die('Administrator required.','',array('response'=>403));$slug=$_GET['page']??'cafcc';$view=array('cafcc'=>'dashboard','cafcc-upload'=>'upload','cafcc-library'=>'library','cafcc-settings'=>'settings','cafcc-students'=>'students')[$slug]??'dashboard';$titles=array('dashboard'=>'Your command center','upload'=>'Upload questions. Publish with confidence.','library'=>'Question Library','students'=>'Students & access','settings'=>'Settings');
        echo '<div class="wrap cc-owner" id="cafcc-owner" data-view="'.esc_attr($view).'"><header class="owner-hero"><span>CA FINAL COMMAND CENTER</span><h1>'.esc_html($titles[$view]).'</h1><p>One package. One owner decision. Every question keeps its identity.</p></header><nav class="owner-nav" aria-label="Command Center">';foreach(array('cafcc'=>'Dashboard','cafcc-upload'=>'Upload Questions','cafcc-library'=>'Question Library','cafcc-students'=>'Students','cafcc-settings'=>'Settings') as $key=>$title)echo '<a '.($slug===$key?'aria-current="page" ':'').'href="'.esc_url(admin_url('admin.php?page='.$key)).'">'.esc_html($title).'</a>';echo '</nav><p id="owner-feedback" role="status" aria-live="polite"></p>';
        if($view==='dashboard')echo '<section id="owner-dashboard" class="owner-panel">Loading actual activity…</section>';
        if($view==='upload')echo '<section class="owner-panel"><h2>1. Choose your academic package</h2><p>Use the compact Academic Import ZIP, including the existing r016 package. PDFs and private evidence stay outside WordPress Media.</p><label class="owner-file">Academic ZIP<input type="file" id="owner-zip" accept=".zip,application/zip"></label><button id="owner-upload" class="owner-primary">Upload & Preview</button><button id="owner-resume">Resume saved work</button><div id="owner-package-preview"></div><label id="owner-rights" hidden><input type="checkbox" id="owner-rights-confirm"> I confirm the displayed source-wide permission declaration. No individual academic verification is implied.</label><div id="owner-import-actions" hidden><button id="owner-drafts">Save as Drafts</button><button id="owner-publish" class="owner-primary">Publish All</button></div><progress id="owner-progress" max="100" value="0" hidden aria-label="Saved import and publication progress"></progress><div id="owner-import-results"></div></section>';
        if($view==='library')echo '<section class="owner-panel"><div class="owner-filters"><label>Dataset<select id="owner-scope"><option value="current">Current pilot dataset</option><option value="historical">Historical drafts</option><option value="archived">Archived / superseded</option><option value="all">All records</option><option value="package">Choose package</option></select></label><label>Package<select id="owner-package"></select></label><label>Search question ID or topic<input id="owner-search" type="search"></label><label>Subject<select id="owner-subject"><option value="">All subjects</option><option>FR</option><option>AFM</option><option value="AUDIT">Audit</option><option>DT</option><option>IDT</option><option>IBS</option></select></label><label>Status<select id="owner-publication"><option value="">Any status</option><option value="published">Published</option><option value="draft">Unpublished</option></select></label></div><p id="owner-library-count"></p><div class="owner-actions"><button id="owner-select-page">Select Current Page</button><button id="owner-select-filter">Select All Filtered</button><button data-owner-bulk="publish" class="owner-primary">Bulk Publish</button><button data-owner-bulk="unpublish">Bulk Unpublish</button><button data-owner-bulk="archive">Archive selected drafts</button><button data-owner-bulk="restore">Restore selected</button></div><div class="owner-scroll"><table><thead><tr><th>Select</th><th>Question ID</th><th>Subject</th><th>Source / attempt</th><th>Question</th><th>Ind AS / SA / Topic</th><th>Publication</th><th>Edit</th></tr></thead><tbody id="owner-library-rows"></tbody></table></div><nav id="owner-library-pages" aria-label="Library pages"></nav></section>';
        if($view==='students'){CAFCC_Access::screen();}
        if($view==='settings'){echo '<section class="owner-panel"><h2>Rights & sources</h2><p>Your source-wide physical permission attestation remains private. Scope, expiry and source identities continue to govern publication.</p><p><a href="'.esc_url(admin_url('admin.php?page=cafcc-rights')).'">Publication Rights</a> · <a href="'.esc_url(admin_url('admin.php?page=cafcc-package')).'">Private Source Register</a></p><details><summary>Standards reference catalogue</summary><p>Ind AS and SA names are checked against ICAI listings. Inferred question tags remain provisional and separate from official hierarchy. Historical amendments remain tied to each source edition. The tagging engine combines retained proposals with local rule-assisted inference; it does not call an external AI provider.</p><p><a href="https://www.icai.org/post/compendium-of-indian-accounting-standards">ICAI Ind AS compendium</a> · <a href="https://www.icai.org/resources.shtml">ICAI auditing resources</a></p></details><details><summary>Advanced Academic Tools</summary><p>Expert tools retain their audit history and server permissions. Everyday publication uses Upload Questions or Question Library.</p><ul>';foreach(self::$advanced as $tool)echo '<li><a href="'.esc_url(admin_url('admin.php?page='.$tool['slug'])).'">'.esc_html($tool['title']).'</a></li>';echo '</ul></details></section>';}
        echo '<dialog id="owner-dialog" aria-label="Review selected publication"><div id="owner-dialog-body"></div></dialog><dialog id="owner-editor" aria-label="Edit question by ID"><div id="owner-editor-body"></div></dialog></div>';
    }
}
